package com.jagan.healthcare.service;
import com.jagan.healthcare.dto.AppointmentRequest; import com.jagan.healthcare.model.Appointment; import com.jagan.healthcare.repository.AppointmentRepository; import org.springframework.stereotype.Service; import java.util.*;
@Service public class AppointmentService { private final AppointmentRepository repository; public AppointmentService(AppointmentRepository repository){this.repository=repository;} public Appointment book(AppointmentRequest r,String sessionEmail){String email=(sessionEmail!=null&&!sessionEmail.isBlank())?sessionEmail:r.getPatientEmail(); if(email==null||email.isBlank())throw new IllegalArgumentException("Please login or provide a valid email."); if(repository.existsByDoctorNameAndAppointmentDateAndAppointmentTimeAndStatus(r.getDoctorName(),r.getAppointmentDate(),r.getAppointmentTime(),"BOOKED"))throw new IllegalArgumentException("That doctor already has a booked appointment at the selected date and time."); return repository.save(new Appointment(r.getPatientName(),email,r.getDoctorName(),r.getAppointmentDate(),r.getAppointmentTime(),r.getReason()));} public List<Appointment> all(){return repository.findAllByOrderByAppointmentDateAscAppointmentTimeAsc();} public List<Appointment> mine(String email){return repository.findByPatientEmailIgnoreCaseOrderByAppointmentDateAscAppointmentTimeAsc(email);} public Appointment cancel(Long id,String email){Appointment a=repository.findById(id).orElseThrow(()->new IllegalArgumentException("Appointment not found."));if(!a.getPatientEmail().equalsIgnoreCase(email))throw new IllegalArgumentException("You can cancel only your own appointment.");if(!"BOOKED".equalsIgnoreCase(a.getStatus()))throw new IllegalArgumentException("Appointment is already cancelled.");a.setStatus("CANCELLED");return repository.save(a);} public Appointment updateStatus(Long id,String status){Appointment a=repository.findById(id).orElseThrow(()->new IllegalArgumentException("Appointment not found."));a.setStatus(status.toUpperCase());return repository.save(a);} }
